// Test doubles: a controllable EventSource, a routed fetch mock, and typed fixtures.
import { vi } from 'vitest'
import type {
  CandidateSummary,
  CompetitorDomain,
  ExecutionEvent,
  ExecutionRun,
  PipelineResult,
  ReviewStatus,
  StompboxProduct,
} from '../api'
import raw from './fixtures/llm-run.json'

// Generated by backend/tests/make_dashboard_fixture.py from the mocked Phase 7 pipeline.
interface Fixture {
  run: ExecutionRun
  result: PipelineResult
  events: ExecutionEvent[]
}
export const fixture = (): Fixture => structuredClone(raw as unknown as Fixture)

export class FakeEventSource {
  static readonly CONNECTING = 0
  static readonly OPEN = 1
  static readonly CLOSED = 2
  static instances: FakeEventSource[] = []

  readonly url: string
  readyState = FakeEventSource.CONNECTING
  onopen: (() => void) | null = null
  onerror: (() => void) | null = null
  closed = false
  private listeners = new Map<string, Set<(e: MessageEvent) => void>>()

  constructor(url: string) {
    this.url = url
    FakeEventSource.instances.push(this)
  }

  addEventListener(type: string, fn: (e: MessageEvent) => void) {
    if (!this.listeners.has(type)) this.listeners.set(type, new Set())
    this.listeners.get(type)!.add(fn)
  }

  removeEventListener(type: string, fn: (e: MessageEvent) => void) {
    this.listeners.get(type)?.delete(fn)
  }

  close() {
    this.readyState = FakeEventSource.CLOSED
    this.closed = true
  }

  // --- test controls ---
  listensTo(type: string) {
    return (this.listeners.get(type)?.size ?? 0) > 0
  }

  open() {
    this.readyState = FakeEventSource.OPEN
    this.onopen?.()
  }

  /** Deliver a named SSE event, as the server does (`event: <type>`). */
  emit(event: ExecutionEvent) {
    const msg = new MessageEvent(event.type, { data: JSON.stringify(event), lastEventId: String(event.seq) })
    this.listeners.get(event.type)?.forEach((fn) => fn(msg))
  }

  /** Connection error. `refused` = the server answered non-200, so the browser gives up. */
  fail(refused = false) {
    this.readyState = refused ? FakeEventSource.CLOSED : FakeEventSource.CONNECTING
    this.onerror?.()
  }
}

export function installEventSource() {
  FakeEventSource.instances = []
  vi.stubGlobal('EventSource', FakeEventSource)
  return FakeEventSource.instances
}

export interface Call {
  method: string
  path: string // pathname + search
  body: unknown
}
type Reply = { status?: number; body: unknown } | undefined
export type Handler = (method: string, path: string, body: unknown) => Reply

/** Route fetch calls to `handler`; unmocked paths get a 500 so tests notice them. */
export function mockApi(handler: Handler) {
  const calls: Call[] = []
  const fn = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = new URL(String(input), 'http://localhost')
    const method = init?.method ?? 'GET'
    const body = typeof init?.body === 'string' ? JSON.parse(init.body) : undefined
    const path = url.pathname + url.search
    calls.push({ method, path, body })
    const reply = handler(method, path, body) ?? { status: 500, body: { detail: `not mocked: ${method} ${path}` } }
    return new Response(JSON.stringify(reply.body), {
      status: reply.status ?? 200,
      headers: { 'Content-Type': 'application/json' },
    })
  })
  vi.stubGlobal('fetch', fn)
  return calls
}

