const competitor = (name: string, domain: string, benchmark: boolean, type: CompetitorDomain['company_type']): CompetitorDomain => ({
  competitor_id: null,
  name,
  domain,
  homepage_url: `https://www.${domain}/`,
  company_type: type,
  classification: benchmark ? 'Retailer' : 'Manufacturer',
  priority: benchmark ? 'Core' : 'Reference only',
  price_benchmark: benchmark,
  approval_status: 'PRECONFIGURED',
  source: 'workbook',
  notes: null,
  relevant_categories: [],
})
export const COMPETITORS = [
  competitor('Andertons', 'andertons.co.uk', true, 'retailer'),
  competitor('Gibson', 'gibson.com', false, 'manufacturer'),
]

export const PRODUCTS = [makeProduct('SB-001', { product_name: 'Boss RC-5 Loop Station Guitar Effect Pedal' }), makeProduct('SB-002')]

export interface AppData {
  run?: ExecutionRun | null // the run behind /api/runs/{id}; null = 404
  result?: PipelineResult
  events?: ExecutionEvent[]
  runs?: ExecutionRun[] // GET /api/runs
  candidates?: CandidateSummary[]
  override?: Handler // checked first
}

/** Full-app API mock with sensible defaults (backend-generated fixture data). */
export function mockAppApi(data: AppData = {}) {
  const f = fixture()
  const run = data.run === undefined ? f.run : data.run
  const result = data.result ?? f.result
  const events = data.events ?? f.events
  const candidates = data.candidates ?? []
  return mockApi((m, p, b) => {
    const o = data.override?.(m, p, b)
    if (o) return o
    if (p === '/api/health') return { body: { status: 'ok', products: 100, competitors: 13 } }
    if (p === '/api/catalogue/products') return { body: { total: PRODUCTS.length, items: PRODUCTS } }
    if (p === '/api/discovery/config')
      return { body: { mode: 'LLM_DISABLED', llm_disabled_reason: 'not set', llm1_model: null, search_provider: 'exa' } }
    if (p === '/api/intelligence/config')
      return {
        body: {
          mode: 'LLM_DISABLED',
          llm_disabled_reason: 'not set',
          llm2_model: null,
          search_provider: 'exa',
          search_targets: f.result.search_targets,
          skipped_targets: [],
          max_products_per_run: 5,
        },
      }
    if (p === '/api/review/candidates') return { body: candidates }
    if (p === '/api/competitors') return { body: COMPETITORS }
    if (m === 'GET' && p === '/api/runs') return { body: data.runs ?? (run ? [run] : []) }
    if (m === 'POST' && p === '/api/runs') return { status: 202, body: run }
    if (run && p === `/api/runs/${run.run_id}`) return { body: run }
    if (run && p === `/api/runs/${run.run_id}/result`) return { body: result }
    const after = p.match(/\/events\?after=(\d+)$/)
    if (after) return { body: events.filter((e) => e.seq > Number(after[1])) }
    if (m === 'POST' && run && p === `/api/runs/${run.run_id}/cancel`) return { status: 202, body: { ...run, cancel_requested: true } }
    if (p.startsWith('/api/runs/')) return { status: 404, body: { detail: 'Run not found' } }
    return undefined
  })
}

/** Put the app at a route before rendering: e.g. at('/?run=x', '#/overview'). */
export function at(search: string, hash = '') {
  window.history.replaceState(null, '', `/${search}${hash}`)
}
